"""Qwen Image 2.1 prompt enhancement via official PE models or an OpenAI-compatible API."""

from __future__ import annotations

import base64
import io
import json
import os
import re
import urllib.request
from typing import Any

import torch
from PIL import Image

import folder_paths

from .qwen_pe_prompts import (
    LANGUAGE_RULE_EN,
    LANGUAGE_RULE_ZH,
    LOCAL_POLICY_ZH,
    NODE_LANGUAGE_HEADER,
    NODE_OVERRIDE_BLOCK,
    QWEN_EDIT_SYSTEM_PROMPT,
    QWEN_T2I_SYSTEM_PROMPT,
)

MAX_REFERENCE_IMAGES = 9
DEFAULT_API_TIMEOUT = 600
MISSING_MODEL_PLACEHOLDER = "（请把 gguf 或 safetensors 模型放到 models/text_encoders 或 models/LLM）"
_LANGUAGE_SECTION_RE = re.compile(r"\n## Language\n[\s\S]*?(?=\n## Output [Ff]ormat|\Z)")
_OUTPUT_FORMAT_RE = re.compile(r"\n## Output [Ff]ormat\n[\s\S]*\Z")
_THINK_RE = re.compile(r"<think>.*?\n</think>\n", re.S | re.I)
_THINK_ZH_RE = re.compile(r"<思考>.*?</思考>")
_EDIT_TAIL = "The user's edit instruction to rewrite is:"
_SHARD_RE = re.compile(r"^(?P<prefix>.+)-(?P<index>\d{5})-of-(?P<total>\d{5})\.gguf$")

_PE_CACHE: dict[tuple[str, int], Any] = {}


def _first(value: Any, default: Any = "") -> Any:
    """Unwrap one value from an INPUT_IS_LIST payload."""
    if isinstance(value, (list, tuple)):
        value = value[0] if len(value) else default
    return default if value is None else value


def _model_dirs() -> list[str]:
    roots: list[str] = []
    for key in ("text_encoders", "LLM", "clip"):
        try:
            roots.extend(folder_paths.get_folder_paths(key))
        except Exception:
            continue
    return [root for root in dict.fromkeys(roots) if os.path.isdir(root)]


def _model_choices() -> list[str]:
    """List GGUF files (first shard only) and HF-style safetensors directories."""
    names: list[str] = []
    for root in _model_dirs():
        for entry in os.scandir(root):
            lower = entry.name.lower()
            if entry.is_dir():
                if os.path.isfile(os.path.join(entry.path, "config.json")):
                    names.append(entry.name)
                continue
            if not (lower.endswith(".gguf") or lower.endswith(".safetensors")):
                continue
            if _SHARD_RE.match(entry.name) and "-00001-of-" not in entry.name:
                continue
            names.append(entry.name)
    return sorted(set(names))


def _resolve_model_path(name: str) -> str:
    for root in _model_dirs():
        path = os.path.join(root, name)
        if os.path.isfile(path):
            return path
    raise ValueError(f"未找到模型文件 {name}，请放入 models/text_encoders 或 models/LLM")


def _validate_gguf_shards(path: str) -> None:
    match = _SHARD_RE.match(os.path.basename(path))
    if not match:
        return
    total = int(match.group("total"))
    prefix = match.group("prefix")
    folder = os.path.dirname(path)
    for index in range(1, total + 1):
        sibling = os.path.join(folder, f"{prefix}-{index:05d}-of-{total:05d}.gguf")
        if not os.path.isfile(sibling):
            raise ValueError(f"GGUF 分片不完整，缺少 {os.path.basename(sibling)}")


def _flatten_reference_images(values: Any, strict: bool = True) -> list[torch.Tensor]:
    """Flatten linked IMAGE lists/batches; order defines <imageN> indices."""
    if values is None:
        return []
    if not isinstance(values, (list, tuple)):
        values = [values]
    images: list[torch.Tensor] = []
    for value in values:
        if not isinstance(value, torch.Tensor):
            if not strict:
                continue
            raise ValueError("参考图输入必须是 IMAGE 张量")
        tensor = value.detach()
        if tensor.ndim == 3:
            tensor = tensor.unsqueeze(0)
        if tensor.ndim != 4:
            raise ValueError("参考图张量维度不正确")
        images.extend(tensor[index] for index in range(tensor.shape[0]))
    if strict and len(images) > MAX_REFERENCE_IMAGES:
        raise ValueError(f"最多支持 {MAX_REFERENCE_IMAGES} 张参考图，当前 {len(images)} 张")
    return images


def _image_to_jpeg_base64(tensor: torch.Tensor, max_edge: int) -> str:
    array = tensor.detach().to(device="cpu", dtype=torch.float32).clamp(0.0, 1.0)
    array = array.mul(255.0).round().to(torch.uint8).numpy()
    if array.shape[-1] == 4:
        image = Image.fromarray(array, mode="RGBA")
    elif array.shape[-1] == 1:
        image = Image.fromarray(array[:, :, 0], mode="L")
    else:
        image = Image.fromarray(array[:, :, :3], mode="RGB")
    scale = (max_edge or 0) / max(image.size)
    if 0 < scale < 1:
        target = (max(1, round(image.width * scale)), max(1, round(image.height * scale)))
        image = image.resize(target, Image.LANCZOS)
    buffer = io.BytesIO()
    image.convert("RGB").save(buffer, format="JPEG", quality=90)
    return "data:image/jpeg;base64," + base64.b64encode(buffer.getvalue()).decode("ascii")


def _build_system_prompt(mode: str, language: str, method: str = "API") -> str:
    if method == "本地官方PE":
        # The official PE model is fine-tuned: plain-text output, so the JSON
        # output section is stripped and node-level plain-text rules apply.
        extra = "\n\n" + NODE_OVERRIDE_BLOCK
        if language == "中文":
            extra += "\n" + LOCAL_POLICY_ZH
    else:
        extra = NODE_LANGUAGE_HEADER + (LANGUAGE_RULE_ZH if language == "中文" else LANGUAGE_RULE_EN)
    if mode == "文生图":
        base = _LANGUAGE_SECTION_RE.sub("\n", QWEN_T2I_SYSTEM_PROMPT)
        if method == "本地官方PE":
            base = _OUTPUT_FORMAT_RE.sub("\n", base)
        return base + extra
    base = QWEN_EDIT_SYSTEM_PROMPT
    if method == "本地官方PE":
        fmt = base.find("\n## Output Format")
        tail_at = base.rfind(_EDIT_TAIL)
        if 0 <= fmt < tail_at:
            base = base[: fmt + 1] + base[tail_at:]
    index = base.rfind(_EDIT_TAIL)
    if index < 0:
        return base + extra
    return base[:index] + extra.strip("\n") + "\n\n" + base[index:]


def _strip_code_fence(text: str) -> str:
    cleaned = (text or "").strip()
    if cleaned.startswith("```"):
        cleaned = cleaned.split("\n", 1)[-1]
        if cleaned.rstrip().endswith("```"):
            cleaned = cleaned.rstrip()[:-3]
    return cleaned.strip()


def _parse_pe_result(text: str, expect_json: bool = True) -> str:
    """Return the enhanced prompt extracted from model output."""
    cleaned = _THINK_RE.sub("", text or "")
    cleaned = _THINK_ZH_RE.sub("", cleaned)
    if cleaned.lstrip().startswith("<think") and "</think>" not in cleaned:
        return ""
    cleaned = _strip_code_fence(cleaned)
    if expect_json or cleaned[:1] == "{":
        start = cleaned.find("{")
        end = cleaned.rfind("}")
        if start >= 0 and end > start:
            try:
                data = json.loads(cleaned[start : end + 1])
            except json.JSONDecodeError:
                data = None
            if isinstance(data, dict):
                prompt = str(data.get("rewritten_prompt") or "").strip()
                if prompt:
                    return prompt
    return cleaned


def _normalize_api_url(url: str) -> str:
    base = str(url or "").strip().rstrip("/")
    if not base:
        raise ValueError("未配置有效的 API URL")
    if base.endswith("/chat/completions"):
        return base
    if base.endswith("/v1"):
        return base + "/chat/completions"
    return base + "/v1/chat/completions"


def _load_llama_pe(path: str, n_ctx: int) -> Any:
    try:
        from llama_cpp import Llama
    except Exception as exc:
        raise RuntimeError("未检测到 llama-cpp-python（llama_cpp）。请先安装/更新该依赖。") from exc
    return Llama(model_path=path, n_ctx=int(n_ctx), n_gpu_layers=-1, verbose=False)


def _load_comfy_pe(path: str) -> Any:
    """Load single-file PE weights through ComfyUI's own TE stack (bundled tokenizers)."""
    import comfy.sd

    return comfy.sd.load_clip(
        ckpt_paths=[path],
        embedding_directory=folder_paths.get_folder_paths("embeddings"),
        clip_type=comfy.sd.CLIPType.STABLE_DIFFUSION,
    )


def _load_official_pe(model_name: str, n_ctx: int) -> Any:
    path = _resolve_model_path(model_name)
    is_gguf = path.lower().endswith(".gguf")
    key = (path, int(n_ctx) if is_gguf else 0)
    cached = _PE_CACHE.get(key)
    if cached is not None:
        return cached
    if is_gguf:
        _validate_gguf_shards(path)
        loaded = ("llama", _load_llama_pe(path, n_ctx))
    else:
        loaded = ("clip", _load_comfy_pe(path))
    _PE_CACHE[key] = loaded
    return loaded


def _generate_clip(clip: Any, system: str, user_text: str, max_tokens: int, seed: int, think: bool) -> str:
    """Same call convention as ComfyUI core TextGenerate: tokenize -> generate -> decode."""
    kwargs: dict[str, Any] = {
        "skip_template": False,
        "min_length": 1,
        "thinking": bool(think),
        "system_prompt": system,
    }
    try:
        tokens = clip.tokenize(user_text, **kwargs)
    except TypeError:
        tokens = clip.tokenize(user_text)
    generated = clip.generate(tokens, do_sample=False, max_length=int(max_tokens), seed=int(seed))
    text = str(clip.decode(generated))
    reasoning, _sep, out = text.partition("</think>")
    if not reasoning.lstrip().startswith("<think"):
        out = text
    return out


def _unload_all_pe() -> None:
    for kind, model in list(_PE_CACHE.values()):
        try:
            if kind == "llama":
                model.close()
        except Exception:
            pass
    _PE_CACHE.clear()
    try:
        import comfy.model_management as model_management

        model_management.soft_empty_cache()
    except Exception:
        pass


def _request_official_pe(model_name: str, n_ctx: int, system: str, user_text: str, max_tokens: int, seed: int, think: bool) -> str:
    kind, model = _load_official_pe(model_name, n_ctx)
    if kind == "clip":
        return _generate_clip(model, system, user_text, max_tokens, seed, think)
    kwargs: dict[str, Any] = {
        "max_tokens": int(max_tokens),
        "seed": int(seed),
        "temperature": 0.2,
        "top_p": 0.9,
        "stream": False,
    }
    if think:
        kwargs["extra_template_arguments"] = {"enable_thinking": True}
    messages = [
        {"role": "system", "content": system},
        {"role": "user", "content": user_text},
    ]
    try:
        result = model.create_chat_completion(messages=messages, **kwargs)
    except TypeError:
        kwargs.pop("extra_template_arguments", None)
        result = model.create_chat_completion(messages=messages, **kwargs)
    return str(result["choices"][0]["message"]["content"] or "")


def _request_api(api_url: str, api_key: str, model_name: str, system: str, user_text: str, images_b64: list[str], max_tokens: int) -> str:
    parts: list[dict[str, Any]] = [
        {"type": "image_url", "image_url": {"url": item}} for item in images_b64
    ]
    parts.append({"type": "text", "text": user_text})
    payload = {
        "model": model_name,
        "messages": [
            {"role": "system", "content": system},
            {"role": "user", "content": parts},
        ],
        "max_tokens": int(max_tokens),
    }
    request = urllib.request.Request(
        _normalize_api_url(api_url),
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json", "Authorization": f"Bearer {api_key}"},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=DEFAULT_API_TIMEOUT) as response:
        data = json.loads(response.read().decode("utf-8"))
    return str(data["choices"][0]["message"]["content"] or "")


class QQQwenImage21PromptEnhancer:
    """Enhance Qwen Image 2.1 prompts with the official PE rules, locally or via API."""

    CATEGORY = "QQ/工具"
    FUNCTION = "enhance"
    INPUT_IS_LIST = True
    RETURN_TYPES = ("STRING",)
    RETURN_NAMES = ("增强提示词",)
    DESCRIPTION = (
        "按 Qwen Image 2.1 官方规则增强文生图/图生图提示词；"
        "本地官方PE 使用 GGUF 版 PE 模型，API 使用 OpenAI 兼容接口并发送参考图；"
        "参考图单口接入，顺序即 <imageN> 序号，最多 9 张。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        choices = _model_choices() or [MISSING_MODEL_PLACEHOLDER]
        return {
            "required": {
                "输入提示词": ("STRING", {"default": "", "multiline": True, "tooltip": "输入要增强的文生图或图生图需求。"}),
                "任务模式": (["自动", "文生图", "图生图"], {"default": "自动", "tooltip": "自动=接了参考图走图生图，否则文生图。"}),
                "增强方式": (["本地官方PE", "API"], {"default": "本地官方PE"}),
                "输出语言": (["中文", "英文"], {"default": "中文", "tooltip": "控制增强提示词的描述语言；用户指定的画面文字保持原文。"}),
                "文生图PE模型": (choices, {"tooltip": "仅本地官方PE且未接参考图时生效。"}),
                "图生图PE模型": (choices, {"tooltip": "仅本地官方PE且接了参考图时生效。"}),
                "API地址": ("STRING", {"default": "", "tooltip": "OpenAI 兼容地址；可填 base、/v1 或完整 chat/completions 地址。仅 API 方式生效。"}),
                "API密钥": ("STRING", {"default": "", "tooltip": "仅 API 方式生效；会随工作流保存。"}),
                "API模型名": ("STRING", {"default": "", "tooltip": "仅 API 方式生效。"}),
                "最大生成token": ("INT", {"default": 2048, "min": 64, "max": 131072, "step": 64}),
                "上下文长度": ("INT", {"default": 8192, "min": 1024, "max": 262144, "step": 256, "tooltip": "仅本地官方PE生效。"}),
                "seed": ("INT", {"default": 0, "min": 0, "max": 0xFFFFFFFFFFFFFFFF, "step": 1, "control_after_generate": True, "tooltip": "仅本地官方PE生效。"}),
                "启用思考": ("BOOLEAN", {"default": False, "tooltip": "仅本地官方PE生效；模型模板支持时开启 enable_thinking。"}),
                "生成后自动卸载": ("BOOLEAN", {"default": False, "tooltip": "本地官方PE生成完成后卸载模型释放显存。"}),
                "最大边长": ("INT", {"default": 1024, "min": 128, "max": 4096, "step": 64, "tooltip": "API 方式发送参考图前的等比缩放上限。"}),
            },
            "optional": {
                "reference_images": ("IMAGE", {"tooltip": "单口多图：顺序即 <imageN> 序号，最多 9 张；可接 QQ-多媒体加载 的 multi output。"}),
            },
        }

    @classmethod
    def VALIDATE_INPUTS(cls, **kwargs: Any):
        method = str(_first(kwargs.get("增强方式"), "本地官方PE") or "本地官方PE")
        images = _flatten_reference_images(kwargs.get("reference_images"), strict=False)
        if len(images) > MAX_REFERENCE_IMAGES:
            return f"最多支持 {MAX_REFERENCE_IMAGES} 张参考图，当前 {len(images)} 张"
        if method == "API":
            if not str(_first(kwargs.get("API地址")) or "").strip():
                return "API 方式需要填写 API地址"
            if not str(_first(kwargs.get("API密钥")) or "").strip():
                return "API 方式需要填写 API密钥"
            if not str(_first(kwargs.get("API模型名")) or "").strip():
                return "API 方式需要填写 API模型名"
            return True
        linked_unknown = isinstance(kwargs.get("reference_images"), (list, tuple)) and any(
            isinstance(item, (list, tuple)) for item in kwargs.get("reference_images") or []
        )
        task_mode = str(_first(kwargs.get("任务模式"), "自动") or "自动")
        if task_mode == "自动":
            use_edit = bool(images) or linked_unknown
        else:
            use_edit = task_mode == "图生图"
        model_name = str(_first(kwargs.get("图生图PE模型" if use_edit else "文生图PE模型")) or "")
        if not model_name or model_name.startswith("（"):
            return "请选择本地官方PE模型，或把 GGUF 模型放入 models/text_encoders / models/LLM"
        try:
            _validate_gguf_shards(_resolve_model_path(model_name))
        except ValueError as exc:
            return str(exc)
        return True

    def enhance(self, **kwargs: Any):
        prompt = str(_first(kwargs.get("输入提示词")) or "")
        if not prompt.strip():
            raise ValueError("输入提示词为空")
        method = str(_first(kwargs.get("增强方式"), "本地官方PE") or "本地官方PE")
        language = str(_first(kwargs.get("输出语言"), "中文") or "中文")
        images = _flatten_reference_images(kwargs.get("reference_images"))
        task_mode = str(_first(kwargs.get("任务模式"), "自动") or "自动")
        if task_mode == "自动":
            mode = "图生图" if images else "文生图"
        else:
            mode = task_mode
        system = _build_system_prompt(mode, language)
        max_tokens = int(_first(kwargs.get("最大生成token"), 2048) or 2048)
        if mode == "文生图":
            user_text = "User Raw Input Prompt: " + prompt
        else:
            user_text = f"参考图数量：{len(images)}，引用标签 <image1> 到 <image{len(images)}>。\n" + prompt
        if method == "API":
            raw = _request_api(
                str(_first(kwargs.get("API地址")) or ""),
                str(_first(kwargs.get("API密钥")) or ""),
                str(_first(kwargs.get("API模型名")) or ""),
                system,
                user_text,
                [_image_to_jpeg_base64(item, int(_first(kwargs.get("最大边长"), 1024) or 1024)) for item in images],
                max_tokens,
            )
        else:
            model_name = str(_first(kwargs.get("图生图PE模型" if mode == "图生图" else "文生图PE模型")) or "")
            if not model_name or model_name.startswith("（"):
                raise ValueError("请选择本地官方PE模型，或把 GGUF 模型放入 models/text_encoders / models/LLM")
            raw = _request_official_pe(
                model_name,
                int(_first(kwargs.get("上下文长度"), 8192) or 8192),
                system,
                user_text,
                max_tokens,
                int(_first(kwargs.get("seed"), 0) or 0),
                bool(_first(kwargs.get("启用思考"), False)),
            )
            if bool(_first(kwargs.get("生成后自动卸载"), False)):
                _unload_all_pe()
        enhanced = _parse_pe_result(raw, expect_json=(method == "API"))
        if not enhanced:
            raise RuntimeError("模型返回为空，可能只生成了思考内容但没有最终提示词，请提高最大生成token后重试")
        return (enhanced,)


NODE_CLASS_MAPPINGS = {"QQQwenImage21PromptEnhancer": QQQwenImage21PromptEnhancer}
NODE_DISPLAY_NAME_MAPPINGS = {"QQQwenImage21PromptEnhancer": "QQ-Qwen Image 2.1 提示词增强"}
